q:
Points $A_1,A_2,A_3,A_4,A_5$ lie on a circle of radius $1$ in this order and satisfy
$$\angle A_5A_2A_4=\angle A_1A_3A_5=\angle A_2A_4A_1=\angle A_3A_5A_2=30^\circ.$$
Let $B_1,B_2,B_3,B_4,B_5$ be the intersections of $A_2A_4$ with $A_3A_5$, $A_3A_5$ with $A_4A_1$, $A_4A_1$ with $A_5A_2$, $A_5A_2$ with $A_1A_3$, and $A_1A_3$ with $A_2A_4$, respectively. Find the area of pentagon $B_1B_2B_3B_4B_5$.

[asy]
import geometry;
settings.tex="none";
defaultpen(black+linewidth(0.65));
real cross2(pair u,pair v) {return u.x*v.y-u.y*v.x;}
pair meet(pair p,pair v,pair q,pair w) {return p+cross2(q-p,w)/cross2(v,w)*v;}
size(270);
pair[] A={dir(90),dir(150),dir(210),dir(330),dir(30)};
pair[] B;
for(int k=0;k<5;++k) B.push(meet(A[(k+1)%5],A[(k+3)%5]-A[(k+1)%5],A[(k+2)%5],A[(k+4)%5]-A[(k+2)%5]));
path pent=B[0];for(int k=1;k<5;++k) pent=pent--B[k];pent=pent--cycle;
fill(pent,gray(0.85));
for(real x=-1;x<1;x+=0.075){path h=(x,-1)--(x+1,1);picture pic;draw(pic,h,linewidth(0.35));clip(pic,pent);add(pic);}
draw(unitcircle);for(int k=0;k<5;++k)draw(A[k]--A[(k+2)%5]);
string[] an={"A1","A2","A3","A4","A5"},bn={"B1","B2","B3","B4","B5"};
pair[] ba={S,E,NE,NW,W};
for(int k=0;k<5;++k){label(an[k],A[k],unit(A[k]));label(bn[k],B[k],ba[k]);}
label("30",A[1]+(0.27,-0.05),(0,-1));label("30",A[2]+(0.16,0.24),(1,0));
label("30",A[3]+(-0.15,0.24),(-1,0));label("30",A[4]+(-0.27,-0.05),(0,-1));
[/asy]
